<script>
import { state, derived } from 'svelte';
const text = state('');
const wordCount = derived(() => {
  const words = text.split(' ');
  return words.length;
});
const charCount = derived(() => {
  const chars = text.split('').length;
  return chars;
});
const isLong = derived(() => {
  return wordCount > 15;
});
</script>
<div>
  <input data-testid="text-input" type="text" bind:value={text} />
  <button data-testid="clear-button" onclick={() => text = ''}>Clear</button>
  <div>
    <p data-testid="word-count">Words: {wordCount}</p>
    <p data-testid="char-count">Characters: {charCount}</p>
    <p data-testid="length-indicator">Status: {isLong ? 'Long text' : 'Short text'}</p>
  </div>
</div>
