<script>
import { inspect } from 'svelte';
const text = $state('Hello world');
inspect(text).with(() => {
  const { count } = $state({
    value: 0
  });
  $effect(() => {
    count.value += 1;
  });
  return () => count.value -= 1;
});
</script>
